//==========================================================
// SECTION 19: DocsDoodads.COLLISION (PRESETS & SAT RUNTIME)
//==========================================================
DocsDoodads.Collision = {
    presets: {
        none: null,
        full: { x: 0, y: 0, w: 1, h: 1 },
        bottomHalf: { x: 0, y: 0.5, w: 1, h: 0.5 },
        bottomThird: { x: 0, y: 0.67, w: 1, h: 0.33 },
        center: { x: 0.25, y: 0.25, w: 0.5, h: 0.5 },
        trunk: { x: 0.35, y: 0.75, w: 0.3, h: 0.25 },
        thinWall: { x: 0, y: 0.4, w: 1, h: 0.2 },
        wideWall: { x: 0, y: 0.25, w: 1, h: 0.5 },
        custom: { x: 0.2, y: 0.2, w: 0.6, h: 0.6 }
    },

    getPresetShape(presetName) {
        return this.presets[presetName] || null;
    },

    // The solid footprint at the bottom of a sprite (a tree's trunk, a wall's base) as a shape
    // relative to the frame. Faint pixels such as soft shadows and anti-aliasing are ignored.
    footprintFromAlpha(data, width, height, options = {}) {
        const frame = options.frame || { x: 0, y: 0, w: width, h: height };
        const threshold = options.alphaThreshold !== undefined ? options.alphaThreshold : 48;
        const fw = Math.max(1, Math.min(frame.w, width - frame.x));
        const fh = Math.max(1, Math.min(frame.h, height - frame.y));
        const solid = (px, py) => data[((frame.y + py) * width + frame.x + px) * 4 + 3] >= threshold;

        let top = -1, bottom = -1;
        for (let py = 0; py < fh; py++) {
            for (let px = 0; px < fw; px++) {
                if (solid(px, py)) {
                    if (top < 0) top = py;
                    bottom = py;
                    break;
                }
            }
        }
        if (bottom < 0) return null;

        const contentH = bottom - top + 1;
        const ratio = options.bandRatio !== undefined ? options.bandRatio : 0.25;
        const minBand = options.minBandPx !== undefined ? options.minBandPx : 4;
        const maxBand = options.maxBandPx !== undefined ? options.maxBandPx : 32;
        const band = Math.max(1, Math.min(contentH, Math.max(minBand, Math.min(maxBand, Math.round(contentH * ratio)))));
        const bandTop = bottom - band + 1;
        const columnFill = options.columnFill !== undefined ? options.columnFill : 0.3;

        let minCol = -1, maxCol = -1;
        for (let px = 0; px < fw; px++) {
            let count = 0;
            for (let py = bandTop; py <= bottom; py++) if (solid(px, py)) count++;
            if (count / band >= columnFill) {
                if (minCol < 0) minCol = px;
                maxCol = px;
            }
        }
        if (minCol < 0) return null;
        const round = v => Math.round(v * 10000) / 10000;
        return { x: round(minCol / fw), y: round(bandTop / fh), w: round((maxCol - minCol + 1) / fw), h: round(band / fh) };
    }
};

// A doodad's collision body in map pixels ({ x, y, w, h }), or null when it has none.
DocsDoodads.Collision.bodyOf = function(dData) {
    if (!dData || !dData.collision || dData.collision.preset === "none") return null;
    const shape = dData.collision.shape || DocsDoodads.Collision.getPresetShape(dData.collision.preset);
    if (!shape) return null;
    const dw = (dData.frameW || 48) * (dData.scaleX || 1);
    const dh = (dData.frameH || 48) * (dData.scaleY || 1);
    const ax = dData.anchorX !== undefined ? dData.anchorX : 0.5;
    const ay = dData.anchorY !== undefined ? dData.anchorY : 1.0;
    const originX = dData.x - dw * ax;
    const originY = dData.y - dh * ay;
    return DocsDoodads.box(originX + shape.x * dw + (shape.w * dw) / 2, originY + shape.y * dh + (shape.h * dh) / 2, shape.w * dw, shape.h * dh);
};

// The box a tile is tested with: two thirds of the tile, at its centre.
DocsDoodads.Collision.tileBox = function(tx, ty, tw, th) {
    return DocsDoodads.box(tx * tw + tw / 2, ty * th + th / 2, tw * 2 / 3, th * 2 / 3);
};

// The tiles a collision body blocks (by the same test as blocksTile).
DocsDoodads.Collision.tilesUnder = function(body, tw, th) {
    if (!body) return [];
    const out = [];
    for (let ty = Math.floor(body.y / th) - 1; ty <= Math.floor((body.y + body.h) / th) + 1; ty++) {
        for (let tx = Math.floor(body.x / tw) - 1; tx <= Math.floor((body.x + body.w) / tw) + 1; tx++) {
            if (DocsDoodads.judge(body, this.tileBox(tx, ty, tw, th))) out.push({ x: tx, y: ty });
        }
    }
    return out;
};

// Whether a showing doodad's collision covers a map tile (a box two thirds of a tile, at its centre).
// Doodads hidden by their switch, condition, season or a layer hidden in game never block, nor do
// doodads in a state without collision (an open door).
DocsDoodads.Collision.blocksTile = function(tx, ty) {
    const doodads = DocsDoodads.doodads();
    if (!doodads || doodads.length === 0) return false;
    const tw = $gameMap.tileWidth(), th = $gameMap.tileHeight();
    const tileBox = this.tileBox(tx, ty, tw, th);
    const mapSettings = DocsDoodads.Lighting.mapSettings($gameMap.mapId());
    for (const dData of doodads) {
        const colBody = this.bodyOf(dData);
        if (!colBody) continue;
        // The box test is cheap; switches and conditions are only checked for doodads on this tile.
        if (!DocsDoodads.judge(colBody, tileBox)) continue;
        if (DocsDoodads.Layers.visibleInGame(dData, mapSettings) && DocsDoodads.Appearance.isVisible(dData, {}) && DocsDoodads.States.blocks(dData)) return true;
    }
    return false;
};

if (typeof Game_CharacterBase !== 'undefined') {
    const _Game_CharacterBase_canPass = Game_CharacterBase.prototype.canPass;
    Game_CharacterBase.prototype.canPass = function(x, y, d) {
        if (!_Game_CharacterBase_canPass.apply(this, arguments)) return false;
        // Through characters (and Ctrl-walking in a playtest), the party in an airship, and anyone
        // flying (Traversal) pass doodads too.
        if (this.isThrough() || this.isDebugThrough()) return true;
        if (this.isInAirship && this.isInAirship()) return true;
        if (DocsDoodads.Traversal && DocsDoodads.Traversal.isFlying(this)) return true;
        return !DocsDoodads.Collision.blocksTile($gameMap.roundXWithDirection(x, d), $gameMap.roundYWithDirection(y, d));
    };
}

//==========================================================
// SECTION 19B: PLACEMENT TOOLS (PATHS, SCATTER, GUIDES, PREFABS, MAP LINKS)
//==========================================================
DocsDoodads.Paths = {
    // Catmull-Rom through the clicked points; the ends stay where they were clicked.
    smooth(points, steps = 8) {
        if (!points || points.length < 3) return (points || []).slice();
        const out = [];
        for (let i = 0; i < points.length - 1; i++) {
            const p0 = points[Math.max(0, i - 1)], p1 = points[i], p2 = points[i + 1], p3 = points[Math.min(points.length - 1, i + 2)];
            for (let s = 0; s < steps; s++) {
                const t = s / steps, t2 = t * t, t3 = t2 * t;
                const f = (a, b, c, d) => 0.5 * ((2 * b) + (-a + c) * t + (2 * a - 5 * b + 4 * c - d) * t2 + (-a + 3 * b - 3 * c + d) * t3);
                out.push({ x: f(p0.x, p1.x, p2.x, p3.x), y: f(p0.y, p1.y, p2.y, p3.y) });
            }
        }
        out.push({ x: points[points.length - 1].x, y: points[points.length - 1].y });
        return out;
    },

    angleOf(a, b) {
        return Math.atan2(b.y - a.y, b.x - a.x) * 180 / Math.PI;
    },

    // Evenly spaced placements along the path. Sharp turns become "corner" pieces at the vertex,
    // and each straight run is spaced so its pieces meet the corners exactly.
    sample(points, spacing, options = {}) {
        const pts = (options.smooth ? this.smooth(points) : points || []).map(p => ({ x: p.x, y: p.y }));
        if (pts.length === 0) return [];
        if (pts.length === 1) return [{ x: pts[0].x, y: pts[0].y, angle: 0, kind: 'start' }];
        spacing = Math.max(4, Number(spacing) || 48);
        const cornerAngle = options.cornerAngle !== undefined ? options.cornerAngle : 35;

        // Split the polyline into runs at sharp vertices.
        const runs = [];
        let run = [pts[0]];
        for (let i = 1; i < pts.length; i++) {
            run.push(pts[i]);
            if (i < pts.length - 1 && !options.smooth) {
                let turn = Math.abs(this.angleOf(pts[i], pts[i + 1]) - this.angleOf(pts[i - 1], pts[i])) % 360;
                if (turn > 180) turn = 360 - turn;
                if (turn >= cornerAngle) {
                    runs.push(run);
                    run = [pts[i]];
                }
            }
        }
        runs.push(run);

        const out = [];
        runs.forEach((r, runIndex) => {
            const lengths = [];
            let total = 0;
            for (let i = 1; i < r.length; i++) {
                const len = Math.hypot(r[i].x - r[i - 1].x, r[i].y - r[i - 1].y);
                lengths.push(len);
                total += len;
            }
            const n = Math.max(1, Math.round(total / spacing));
            const pointAt = (dist) => {
                let seg = 0;
                while (seg < lengths.length - 1 && dist > lengths[seg]) { dist -= lengths[seg]; seg++; }
                const a = r[seg], b = r[seg + 1];
                const k = lengths[seg] > 0 ? Math.min(1, dist / lengths[seg]) : 0;
                return { x: a.x + (b.x - a.x) * k, y: a.y + (b.y - a.y) * k, angle: this.angleOf(a, b) };
            };
            for (let i = runIndex === 0 ? 0 : 1; i <= n; i++) {
                const p = pointAt(total * i / n);
                const isFirst = runIndex === 0 && i === 0;
                const isLast = runIndex === runs.length - 1 && i === n;
                const kind = isFirst ? 'start' : isLast ? 'end' : i === n ? 'corner' : 'segment';
                out.push({ x: Math.round(p.x * 100) / 100, y: Math.round(p.y * 100) / 100, angle: Math.round(p.angle * 100) / 100, kind });
            }
        });
        return out;
    }
};

DocsDoodads.Scatter = {
    // Small seeded generator so a stroke can be reproduced in tests.
    rng(seed) {
        let a = (Number(seed) || 1) >>> 0;
        return () => {
            a = (a + 0x6D2B79F5) >>> 0;
            let t = a;
            t = Math.imul(t ^ (t >>> 15), t | 1);
            t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
            return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        };
    },

    // Poisson-disk style dart throwing: no two props closer than minDistance, existing props included.
    candidates(center, radius, minDistance, existing, count, rng, maxAttempts) {
        const accepted = [];
        const others = (existing || []).slice();
        const attempts = maxAttempts || Math.max(30, count * 30);
        for (let i = 0; i < attempts && accepted.length < count; i++) {
            const angle = rng() * Math.PI * 2;
            const dist = radius * Math.sqrt(rng());
            const p = { x: center.x + Math.cos(angle) * dist, y: center.y + Math.sin(angle) * dist };
            if (minDistance > 0 && others.some(o => Math.hypot(o.x - p.x, o.y - p.y) < minDistance)) continue;
            accepted.push(p);
            others.push(p);
        }
        return accepted;
    },

    parseIdList(text) {
        return String(text || '').split(/[^0-9]+/).filter(Boolean).map(n => parseInt(n, 10)).filter(n => n > 0);
    },

    allowed(point, rules, query) {
        const tw = query.tileWidth || 48, th = query.tileHeight || 48;
        const tx = Math.floor(point.x / tw), ty = Math.floor(point.y / th);
        if (point.x < 0 || point.y < 0 || tx >= query.width || ty >= query.height) return false;
        rules = rules || {};
        if (rules.regions && rules.regions.length > 0 && !rules.regions.includes(query.regionId(tx, ty))) return false;
        if (rules.terrainTags && rules.terrainTags.length > 0 && !rules.terrainTags.includes(query.terrainTag(tx, ty))) return false;
        if (rules.avoidBlocked && !query.isPassable(tx, ty)) return false;
        return true;
    },

    variation(settings, rng) {
        const jitter = (amount) => (rng() * 2 - 1) * (Number(amount) || 0);
        return {
            scale: Math.round((1 + jitter(settings.scaleJitter)) * 100) / 100,
            rotation: Math.round(jitter(settings.rotateJitter)),
            flipX: rng() < (Number(settings.flipChance) || 0),
            hue: Math.round(jitter(settings.hueJitter))
        };
    }
};

DocsDoodads.Guides = {
    rectOf(d) {
        const w = (d.frameW || 48) * Math.abs(d.scaleX !== undefined ? d.scaleX : 1);
        const h = (d.frameH || 48) * Math.abs(d.scaleY !== undefined ? d.scaleY : 1);
        const left = d.x - w * (d.anchorX !== undefined ? d.anchorX : 0.5);
        const top = d.y - h * (d.anchorY !== undefined ? d.anchorY : 1);
        // base: the line the doodad stands on (its anchor), which is not always its bottom edge.
        return { left, right: left + w, top, bottom: top + h, cx: left + w / 2, cy: top + h / 2, base: d.y };
    },

    unionRect(rects) {
        const r = { left: Infinity, right: -Infinity, top: Infinity, bottom: -Infinity };
        for (const x of rects) {
            r.left = Math.min(r.left, x.left); r.right = Math.max(r.right, x.right);
            r.top = Math.min(r.top, x.top); r.bottom = Math.max(r.bottom, x.bottom);
        }
        r.cx = (r.left + r.right) / 2;
        r.cy = (r.top + r.bottom) / 2;
        // Several doodads move as one: the lowest base line is theirs.
        if (rects.length && rects.every(x => x.base !== undefined)) r.base = Math.max(...rects.map(x => x.base));
        return r;
    },

    // Edge/centre/base alignment first; otherwise equal spacing between the nearest neighbours; otherwise
    // (opts.tile: { w, h }) an edge or the base line on a tile line.
    snap(moving, others, threshold = 6, opts = {}) {
        const result = { dx: 0, dy: 0, lines: [] };
        const m = Object.assign({}, moving);
        if (m.cx === undefined) m.cx = (m.left + m.right) / 2;
        if (m.cy === undefined) m.cy = (m.top + m.bottom) / 2;
        const rects = (others || []).map(o => Object.assign({ cx: (o.left + o.right) / 2, cy: (o.top + o.bottom) / 2 }, o));

        const axis = (keys, crossFrom, crossTo, name) => {
            let best = null;
            for (const o of rects) {
                for (const mk of keys) {
                    for (const ok of keys) {
                        const diff = o[ok] - m[mk];
                        if (Math.abs(diff) <= threshold && (best === null || Math.abs(diff) < Math.abs(best))) best = diff;
                    }
                }
            }
            if (best === null) return null;
            const lines = [];
            for (const o of rects) {
                for (const mk of keys) {
                    for (const ok of keys) {
                        if (Math.abs(o[ok] - (m[mk] + best)) < 0.01) {
                            lines.push({ axis: name, at: o[ok], from: Math.min(o[crossFrom], m[crossFrom]), to: Math.max(o[crossTo], m[crossTo]) });
                        }
                    }
                }
            }
            return { delta: best, lines };
        };

        const spacing = (lo, hi, crossLo, crossHi, name) => {
            const overlapping = rects.filter(o => o[crossLo] < m[crossHi] && o[crossHi] > m[crossLo]);
            const before = overlapping.filter(o => o[hi] <= m[lo]).sort((a, b) => b[hi] - a[hi])[0];
            const after = overlapping.filter(o => o[lo] >= m[hi]).sort((a, b) => a[lo] - b[lo])[0];
            if (!before || !after) return null;
            const gap1 = m[lo] - before[hi], gap2 = after[lo] - m[hi];
            if (Math.abs(gap1 - gap2) > threshold * 2) return null;
            const delta = (gap2 - gap1) / 2;
            const mid = (m[crossLo] + m[crossHi]) / 2;
            return { delta, lines: [
                { axis: name, kind: 'spacing', at: mid, from: before[hi], to: m[lo] + delta },
                { axis: name, kind: 'spacing', at: mid, from: m[hi] + delta, to: after[lo] }
            ] };
        };

        const onTiles = (keys, size, crossFrom, crossTo, name) => {
            if (!(size > 0)) return null;
            let best = null;
            for (const mk of keys) {
                if (!Number.isFinite(m[mk])) continue;
                const diff = Math.round(m[mk] / size) * size - m[mk];
                if (Math.abs(diff) <= threshold && (best === null || Math.abs(diff) < Math.abs(best.delta))) best = { delta: diff, at: m[mk] + diff };
            }
            return best ? { delta: best.delta, lines: [{ axis: name, kind: 'tile', at: best.at, from: m[crossFrom] - size / 2, to: m[crossTo] + size / 2 }] } : null;
        };
        const tile = opts.tile || null;
        const x = axis(['left', 'cx', 'right'], 'top', 'bottom', 'x') || spacing('left', 'right', 'top', 'bottom', 'x-gap') ||
            (tile ? onTiles(['left', 'right'], tile.w, 'top', 'bottom', 'x') : null);
        const y = axis(['top', 'cy', 'bottom', 'base'], 'left', 'right', 'y') || spacing('top', 'bottom', 'left', 'right', 'y-gap') ||
            (tile ? onTiles(['base', 'top', 'bottom'], tile.h, 'left', 'right', 'y') : null);
        if (x) { result.dx = x.delta; result.lines.push(...x.lines); }
        if (y) { result.dy = y.delta; result.lines.push(...y.lines); }
        return result;
    }
};

DocsDoodads.Prefabs = {
    filePath: 'data/DocsDoodadsPrefabs.json',
    list: [],
    loaded: false,

    load() {
        const data = DocsDoodads.FS.readJson(this.filePath);
        this.list = data && Array.isArray(data.prefabs) ? data.prefabs : [];
        this.loaded = true;
        return this.list;
    },

    ensureLoaded() {
        if (!this.loaded) this.load();
        return this.list;
    },

    save() {
        return DocsDoodads.FS.atomicWriteJson(this.filePath, { version: 1, prefabs: this.list });
    },

    get(id) {
        return this.ensureLoaded().find(p => p.id === id) || null;
    },

    add(prefab) {
        this.ensureLoaded().push(prefab);
        return prefab;
    },

    remove(id) {
        const index = this.ensureLoaded().findIndex(p => p.id === id);
        if (index >= 0) this.list.splice(index, 1);
        return index >= 0;
    },

    newId(prefix) {
        return prefix + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
    },

    cleanDoodad(d) {
        const copy = JSON.parse(JSON.stringify(d));
        for (const key of ['groupId', 'prefabRef', 'locked', 'uid', 'mirrorOf', 'editorHidden']) delete copy[key];
        return copy;
    },

    // The origin is the bottom-centre of the doodads' anchor points; events keep tile offsets from it.
    originFor(doodads, events, tw, th) {
        if (doodads.length > 0) {
            const xs = doodads.map(d => d.x), ys = doodads.map(d => d.y);
            return { x: Math.round((Math.min(...xs) + Math.max(...xs)) / 2), y: Math.max(...ys) };
        }
        if (events.length > 0) {
            const xs = events.map(e => e.x), ys = events.map(e => e.y);
            return { x: Math.round((Math.min(...xs) + Math.max(...xs)) / 2 * tw + tw / 2), y: (Math.max(...ys) + 1) * th };
        }
        return { x: 0, y: 0 };
    },

    // Each doodad in a master has a key (pk) that its placed copies keep in prefabRef.pk, so settings a
    // copy keeps as its own (prefabRef.own, a list of Details keys) find their doodad again when copies are
    // rebuilt. A master can hold other prefabs: children [{ key, id, x, y, own }], placed from their own
    // master each time, so changing the inner prefab changes every prefab that holds it. A child's own
    // settings are { innerPk: { key: value } }. Keys of a child's doodads are child.key + '/' + inner key.
    pkOf(src, index) {
        return src && src.pk ? String(src.pk) : 'k' + index;
    },

    // Sets a Details key on a doodad when no editor is there to do it (dot keys set inside the group).
    setProperty(d, key, value) {
        const dot = key.indexOf('.');
        if (dot > 0) {
            const group = key.slice(0, dot);
            d[group] = Object.assign({}, d[group] || {}, { [key.slice(dot + 1)]: value });
        } else {
            d[key] = value;
        }
    },

    // Every doodad the prefab places, positions relative to its origin, and its events with the pixel
    // offset of the origin their tile offsets count from. A prefab inside itself is skipped.
    expand(prefab, options = {}, seen = new Set()) {
        const out = { doodads: [], events: [] };
        if (!prefab || seen.has(prefab.id) || seen.size > 16) return out;
        const inner = new Set(seen).add(prefab.id);
        const apply = options.applyProperty || ((d, key, value) => this.setProperty(d, key, value));
        (prefab.doodads || []).forEach((src, i) => {
            const d = JSON.parse(JSON.stringify(src));
            delete d.pk;
            out.doodads.push({ d, pk: this.pkOf(src, i) });
        });
        (prefab.events || []).forEach(e => out.events.push({ e, ox: 0, oy: 0 }));
        (prefab.children || []).forEach((child, ci) => {
            const master = this.get(child.id);
            if (!master) return;
            const key = child.key || 'c' + ci;
            const placed = this.expand(master, options, inner);
            for (const item of placed.doodads) {
                item.d.x += Number(child.x) || 0;
                item.d.y += Number(child.y) || 0;
                const own = child.own && child.own[item.pk];
                if (own) for (const k of Object.keys(own)) apply(item.d, k, own[k]);
                out.doodads.push({ d: item.d, pk: key + '/' + item.pk });
            }
            for (const ev of placed.events) out.events.push({ e: ev.e, ox: ev.ox + (Number(child.x) || 0), oy: ev.oy + (Number(child.y) || 0) });
        });
        return out;
    },

    // The prefabs that hold this one, however deep.
    containers(prefabId) {
        const found = new Set();
        let frontier = [prefabId];
        while (frontier.length) {
            const next = [];
            for (const p of this.ensureLoaded()) {
                if (found.has(p.id) || p.id === prefabId) continue;
                if ((p.children || []).some(c => frontier.includes(c.id))) { found.add(p.id); next.push(p.id); }
            }
            frontier = next;
        }
        return Array.from(found);
    },

    // Before a prefab is deleted: the prefabs holding it keep what it placed as their own doodads and
    // events (same keys, so placed copies keep their own settings).
    bakeChild(prefabId, options = {}) {
        const tw = options.tileWidth || 48, th = options.tileHeight || 48;
        let count = 0;
        for (const p of this.ensureLoaded()) {
            if (p.id === prefabId || !(p.children || []).some(c => c.id === prefabId)) continue;
            p.children = p.children.filter((child, ci) => {
                if (child.id !== prefabId) return true;
                const key = child.key || 'c' + ci;
                const placed = this.expand({ id: p.id + '/bake', children: [Object.assign({}, child, { key })] }, options);
                for (const item of placed.doodads) p.doodads = (p.doodads || []).concat([Object.assign(item.d, { pk: item.pk })]);
                for (const ev of placed.events) {
                    p.events = (p.events || []).concat([Object.assign(JSON.parse(JSON.stringify(ev.e)), {
                        dx: ev.e.dx + Math.round(ev.ox / tw), dy: ev.e.dy + Math.round(ev.oy / th)
                    })]);
                }
                count++;
                return false;
            });
            if (!p.children.length) delete p.children;
            p.updatedAt = Date.now();
        }
        return count;
    },

    thumbnailFor(prefab) {
        const first = this.expand(prefab).doodads.find(item => item.d.bit && item.d.bit[0] === 3);
        return first ? first.d.bit[1] : '';
    },

    // options: { tileWidth, tileHeight, whole(instance) (every doodad of that placed copy is in the list:
    // it becomes a child prefab), ownValues(d) ({ key: value } for the doodad's own settings) }.
    capture(name, doodads, events, options = {}) {
        const tw = options.tileWidth || 48, th = options.tileHeight || 48;
        doodads = (doodads || []).filter(Boolean);
        events = (events || []).filter(Boolean);
        const origin = this.originFor(doodads, events, tw, th);
        const originTile = { x: Math.floor(origin.x / tw), y: Math.floor((origin.y - 1) / th) };
        // options.onLink(d, pk) hears the key each picked doodad has in the new prefab.
        const children = [], own = [], childOf = new Map(), seenIn = new Map();
        for (const d of doodads) {
            const ref = d.prefabRef;
            if (ref && this.get(ref.id) && options.whole && options.whole(ref.instance)) {
                let child = childOf.get(ref.instance);
                if (!child) {
                    child = { key: 'c' + children.length, id: ref.id, x: Math.round((Number(ref.ox) || 0) - origin.x), y: Math.round((Number(ref.oy) || 0) - origin.y) };
                    childOf.set(ref.instance, child);
                    children.push(child);
                }
                const n = seenIn.get(ref.instance) || 0;
                seenIn.set(ref.instance, n + 1);
                const inner = this.pkOf(ref, n);
                const values = Array.isArray(ref.own) && ref.own.length && options.ownValues ? options.ownValues(d) : null;
                if (values && Object.keys(values).length) (child.own = child.own || {})[inner] = values;
                if (options.onLink) options.onLink(d, child.key + '/' + inner);
            } else {
                if (options.onLink) options.onLink(d, 'k' + own.length);
                own.push(d);
            }
        }
        const prefab = {
            id: this.newId('pf_'),
            name: String(name || 'Prefab').trim() || 'Prefab',
            createdAt: Date.now(),
            origin,
            thumbnail: '',
            doodads: own.map((d, i) => Object.assign(this.cleanDoodad(d), { x: d.x - origin.x, y: d.y - origin.y, pk: 'k' + i })),
            events: events.map(e => Object.assign(JSON.parse(JSON.stringify(e)), { dx: e.x - originTile.x, dy: e.y - originTile.y }))
        };
        if (children.length) prefab.children = children;
        prefab.thumbnail = this.thumbnailFor(prefab);
        return prefab;
    },

    // options: { tileWidth, tileHeight, instance, groupId, allocateEventId, keep ({ pk: { key: value } }: a
    // copy's own settings put back), applyProperty }.
    instantiate(prefab, at, options = {}) {
        const tw = options.tileWidth || 48, th = options.tileHeight || 48;
        const instance = options.instance || this.newId('pi_');
        const groupId = options.groupId || ('grp_' + instance);
        const apply = options.applyProperty || ((d, key, value) => this.setProperty(d, key, value));
        const placed = this.expand(prefab, options);
        const doodads = placed.doodads.map(({ d, pk }) => {
            d.x = Math.round(at.x + d.x);
            d.y = Math.round(at.y + d.y);
            d.groupId = groupId;
            d.prefabRef = { id: prefab.id, instance, ox: at.x, oy: at.y, pk };
            const keep = options.keep && options.keep[pk];
            if (keep && Object.keys(keep).length) {
                for (const key of Object.keys(keep)) apply(d, key, keep[key]);
                d.prefabRef.own = Object.keys(keep);
            }
            return d;
        });
        const events = placed.events.map(({ e: src, ox, oy }) => {
            const e = JSON.parse(JSON.stringify(src));
            e.x = Math.floor((at.x + ox) / tw) + src.dx;
            e.y = Math.floor((at.y + oy - 1) / th) + src.dy;
            delete e.dx;
            delete e.dy;
            e.id = options.allocateEventId ? options.allocateEventId(e) : null;
            return e;
        });
        return { instance, groupId, doodads, events };
    },

    // Recaptures the master from one placed copy (its events are left as they were). The copy's own
    // doodads replace the master's; a child prefab moves with its doodads and keeps the copy's own settings
    // for them. options: { ownValues(d) }.
    updateFromInstance(prefab, instanceDoodads, options = {}) {
        if (!prefab || !instanceDoodads || instanceDoodads.length === 0) return null;
        const ref = instanceDoodads[0].prefabRef;
        const inChild = d => Boolean(d.prefabRef && String(d.prefabRef.pk || '').indexOf('/') > 0);
        const expected = this.expand(prefab).doodads;
        prefab.doodads = instanceDoodads.filter(d => !inChild(d)).map((d, i) =>
            Object.assign(this.cleanDoodad(d), { x: d.x - ref.ox, y: d.y - ref.oy, pk: (d.prefabRef && d.prefabRef.pk) || 'k' + i }));
        (prefab.children || []).forEach((child, ci) => {
            const key = child.key || 'c' + ci;
            const mine = instanceDoodads.filter(d => inChild(d) && String(d.prefabRef.pk).indexOf(key + '/') === 0);
            if (!mine.length) return;
            const was = expected.find(item => item.pk === mine[0].prefabRef.pk);
            if (was) {
                child.x = (Number(child.x) || 0) + Math.round(mine[0].x - ref.ox - was.d.x);
                child.y = (Number(child.y) || 0) + Math.round(mine[0].y - ref.oy - was.d.y);
            }
            // What the child already changed stays; the copy's own settings are added on top.
            const own = JSON.parse(JSON.stringify(child.own || {}));
            for (const d of mine) {
                const values = Array.isArray(d.prefabRef.own) && d.prefabRef.own.length && options.ownValues ? options.ownValues(d) : null;
                const inner = String(d.prefabRef.pk).slice(key.length + 1);
                if (values && Object.keys(values).length) own[inner] = Object.assign(own[inner] || {}, values);
            }
            if (Object.keys(own).length) child.own = own; else delete child.own;
        });
        prefab.thumbnail = this.thumbnailFor(prefab) || prefab.thumbnail;
        prefab.updatedAt = Date.now();
        return prefab;
    }
};

DocsDoodads.MapLinks = {
    sides: ['east', 'west', 'north', 'south'],

    ensureUid(d) {
        if (!d.uid) d.uid = 'dd_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
        return d;
    },

    // World positions (pixels) of the current map and its linked neighbours, up to depth links away.
    layout(mapId, neighborsOf, sizeOf, depth = 2) {
        const start = sizeOf(mapId);
        if (!start) return [];
        const placed = [{ mapId, x: 0, y: 0, w: start.w, h: start.h, distance: 0 }];
        const seen = new Set([mapId]);
        for (let i = 0; i < placed.length; i++) {
            const m = placed[i];
            if (m.distance >= depth) continue;
            const links = neighborsOf(m.mapId) || {};
            for (const side of this.sides) {
                const id = Number(links[side]);
                if (!id || seen.has(id)) continue;
                const size = sizeOf(id);
                if (!size) continue;
                seen.add(id);
                const x = side === 'east' ? m.x + m.w : side === 'west' ? m.x - size.w : m.x;
                const y = side === 'south' ? m.y + m.h : side === 'north' ? m.y - size.h : m.y;
                placed.push({ mapId: id, x, y, w: size.w, h: size.h, distance: m.distance + 1 });
            }
        }
        return placed;
    },

    bounds(layout) {
        return {
            left: Math.min(...layout.map(m => m.x)), top: Math.min(...layout.map(m => m.y)),
            right: Math.max(...layout.map(m => m.x + m.w)), bottom: Math.max(...layout.map(m => m.y + m.h))
        };
    },

    // Copies of doodads that hang over this map's edges, shifted into each neighbouring map.
    edgeCopies(mapId, doodads, neighbors, sizeOf) {
        const out = [];
        const size = sizeOf(mapId);
        if (!size || !neighbors) return out;
        for (const d of doodads || []) {
            if (!d || d.mirrorOf || d.posMode === 0) continue;
            const r = DocsDoodads.Guides.rectOf(d);
            const shifts = [];
            if (neighbors.east && r.right > size.w) shifts.push({ mapId: neighbors.east, dx: -size.w, dy: 0 });
            if (neighbors.west && r.left < 0) { const s = sizeOf(neighbors.west); if (s) shifts.push({ mapId: neighbors.west, dx: s.w, dy: 0 }); }
            if (neighbors.south && r.bottom > size.h) shifts.push({ mapId: neighbors.south, dx: 0, dy: -size.h });
            if (neighbors.north && r.top < 0) { const s = sizeOf(neighbors.north); if (s) shifts.push({ mapId: neighbors.north, dx: 0, dy: s.h }); }
            for (const shift of shifts) {
                const copy = DocsDoodads.Prefabs.cleanDoodad(d);
                copy.x = d.x + shift.dx;
                copy.y = d.y + shift.dy;
                copy.mirrorOf = { mapId, uid: d.uid };
                out.push({ mapId: Number(shift.mapId), doodad: copy });
            }
        }
        return out;
    }
};

//==========================================================
// SECTION 19C: ROOM STAMPS
//==========================================================
// A rectangle of map saved as a stamp: its tiles (all six layers: four tile layers, shadows and
// regions), the doodads standing in it and the events on it, to place again here or on another map.
// Stamps are kept in data/DocsDoodadsRooms.json. Tiles are MZ's map data (index (z * h + y) * w + x).
DocsDoodads.Rooms = {
    filePath: 'data/DocsDoodadsRooms.json',
    layers: 6,
    list: [],
    loaded: false,

    load() {
        const data = DocsDoodads.FS.readJson(this.filePath);
        this.list = data && Array.isArray(data.rooms) ? data.rooms : [];
        this.loaded = true;
        return this.list;
    },

    ensureLoaded() {
        if (!this.loaded) this.load();
        return this.list;
    },

    save() {
        return DocsDoodads.FS.atomicWriteJson(this.filePath, { version: 1, rooms: this.ensureLoaded() });
    },

    get(id) {
        return this.ensureLoaded().find(r => r.id === id) || null;
    },

    add(room) {
        this.ensureLoaded().push(room);
        return room;
    },

    remove(id) {
        const i = this.ensureLoaded().findIndex(r => r.id === id);
        if (i >= 0) this.list.splice(i, 1);
        return i >= 0;
    },

    index(w, h, x, y, z) {
        return (z * h + y) * w + x;
    },

    // The rectangle between two tiles, inside the map.
    rectBetween(a, b, mapW, mapH) {
        const x0 = Math.max(0, Math.min(a.x, b.x)), y0 = Math.max(0, Math.min(a.y, b.y));
        const x1 = Math.min(mapW - 1, Math.max(a.x, b.x)), y1 = Math.min(mapH - 1, Math.max(a.y, b.y));
        return { x: x0, y: y0, w: Math.max(0, x1 - x0 + 1), h: Math.max(0, y1 - y0 + 1) };
    },

    // map: { width, height, data }; rect in tiles; doodads (pixels) and events (tiles) of the map.
    capture(name, map, rect, doodads, events, tw = 48, th = 48) {
        const W = Number(map.width) || 0, H = Number(map.height) || 0;
        const tiles = new Array(rect.w * rect.h * this.layers).fill(0);
        for (let z = 0; z < this.layers; z++) {
            for (let y = 0; y < rect.h; y++) {
                for (let x = 0; x < rect.w; x++) {
                    tiles[this.index(rect.w, rect.h, x, y, z)] = Number(map.data[this.index(W, H, rect.x + x, rect.y + y, z)]) || 0;
                }
            }
        }
        const left = rect.x * tw, top = rect.y * th, right = (rect.x + rect.w) * tw, bottom = (rect.y + rect.h) * th;
        // A doodad belongs to the room when it stands in it (its anchor point, at its foot).
        const inside = (doodads || []).filter(d => d && d.x >= left && d.x < right && d.y > top && d.y <= bottom && !d.mirrorOf);
        return {
            id: DocsDoodads.Prefabs.newId('room_'),
            name: String(name || 'Room').trim() || 'Room',
            createdAt: Date.now(),
            w: rect.w, h: rect.h, tileWidth: tw, tileHeight: th,
            tiles,
            doodads: inside.map(d => Object.assign(DocsDoodads.Prefabs.cleanDoodad(d), { x: d.x - left, y: d.y - top })),
            events: (events || []).filter(e => e && e.x >= rect.x && e.x < rect.x + rect.w && e.y >= rect.y && e.y < rect.y + rect.h)
                .map(e => Object.assign(JSON.parse(JSON.stringify(e)), { dx: e.x - rect.x, dy: e.y - rect.y }))
        };
    },

    // What placing the room with its top-left on tile (at.x, at.y) does. options: { tiles, doodads, events
    // (each on unless false), keepUnder (a tile layer the room leaves empty keeps the map's tile), tileWidth,
    // tileHeight, allocateEventId }. Returns { changes: [{ index, before, after }], doodads, events }; the
    // map is not changed here. Parts outside the map are left off.
    place(room, map, at, options = {}) {
        const W = Number(map.width) || 0, H = Number(map.height) || 0;
        const tw = options.tileWidth || 48, th = options.tileHeight || 48;
        const keepUnder = options.keepUnder !== false;
        const out = { changes: [], doodads: [], events: [] };
        const inMap = (x, y) => x >= 0 && y >= 0 && x < W && y < H;
        if (options.tiles !== false) {
            for (let z = 0; z < this.layers; z++) {
                for (let y = 0; y < room.h; y++) {
                    for (let x = 0; x < room.w; x++) {
                        const mx = at.x + x, my = at.y + y;
                        if (!inMap(mx, my)) continue;
                        const after = Number(room.tiles[this.index(room.w, room.h, x, y, z)]) || 0;
                        // Empty upper layers and no region in the room leave the map's own.
                        if (keepUnder && after === 0 && z > 0) continue;
                        const index = this.index(W, H, mx, my, z);
                        const before = Number(map.data[index]) || 0;
                        if (before !== after) out.changes.push({ index, before, after });
                    }
                }
            }
        }
        // Doodads keep where they stood in the room; their size scales with a different tile size.
        const sx = tw / (room.tileWidth || tw), sy = th / (room.tileHeight || th);
        if (options.doodads !== false) {
            const groupId = 'grp_' + DocsDoodads.Prefabs.newId('rm_');
            for (const src of room.doodads || []) {
                const d = JSON.parse(JSON.stringify(src));
                d.x = Math.round(at.x * tw + src.x * sx);
                d.y = Math.round(at.y * th + src.y * sy);
                if (!inMap(Math.floor(d.x / tw), Math.floor((d.y - 1) / th))) continue;
                if ((room.doodads || []).length > 1) d.groupId = groupId;
                out.doodads.push(d);
            }
        }
        if (options.events !== false) {
            for (const src of room.events || []) {
                const x = at.x + src.dx, y = at.y + src.dy;
                if (!inMap(x, y)) continue;
                const e = JSON.parse(JSON.stringify(src));
                delete e.dx;
                delete e.dy;
                e.x = x;
                e.y = y;
                e.id = options.allocateEventId ? options.allocateEventId(e) : null;
                out.events.push(e);
            }
        }
        return out;
    },

    summary(room) {
        const n = (room.doodads || []).length, e = (room.events || []).length;
        return `${room.w} x ${room.h} tiles` + (n ? `, ${n} doodad${n === 1 ? '' : 's'}` : '') + (e ? `, ${e} event${e === 1 ? '' : 's'}` : '');
    }
};
//==========================================================
// SECTION 19D: TILE PAINTING (MZ TILES AND AUTOTILES)
//==========================================================
// Painting MZ's own tiles in a playtest, autotiles included. Tile ids follow MZ: B-E sheets 0-1023, A5
// 1536+, autotiles from 2048 as kind * 48 + shape. An autotile's shape comes from its neighbours: each
// quarter of the tile takes a piece from the autotile's block, chosen by whether the tiles beside and
// diagonal to that corner are the same kind; the shape is the entry of MZ's own table (Tilemap's floor,
// wall or waterfall table, passed in) with those four pieces. The map edge counts as the same kind.
DocsDoodads.Tiles = {
    B: 0, C: 256, D: 512, E: 768, A5: 1536, A1: 2048, A2: 2816, A3: 4352, A4: 5888, MAX: 8192,
    sheets: ['A1', 'A2', 'A3', 'A4', 'A5', 'B', 'C', 'D', 'E'],

    isAutotile(id) { return id >= this.A1 && id < this.MAX; },
    kind(id) { return Math.floor((id - this.A1) / 48); },
    shape(id) { return (id - this.A1) % 48; },
    make(kind, shape) { return this.A1 + kind * 48 + shape; },
    isA1(id) { return id >= this.A1 && id < this.A2; },
    isA2(id) { return id >= this.A2 && id < this.A3; },
    isA3(id) { return id >= this.A3 && id < this.A4; },
    isA4(id) { return id >= this.A4 && id < this.MAX; },
    isWaterfall(id) { return this.isA1(id) && id >= this.A1 + 192 && this.kind(id) % 2 === 1; },
    isRoof(id) { return this.isA3(id) && this.kind(id) % 16 < 8; },
    isWallTop(id) { return this.isA4(id) && this.kind(id) % 16 < 8; },
    isWallSide(id) { return (this.isA3(id) || this.isA4(id)) && this.kind(id) % 16 >= 8; },
    // 'floor', 'wall', 'waterfall' or null (not an autotile).
    type(id) {
        if (!this.isAutotile(id)) return null;
        if (this.isWaterfall(id)) return 'waterfall';
        if (this.isRoof(id) || this.isWallSide(id)) return 'wall';
        return 'floor';
    },

    // The four pieces [TL, TR, BL, BR] as [x, y] half-tiles in the autotile's block, from its neighbours.
    // n: { l, r, u, d, ul, ur, dl, dr } (true = the same kind there).
    pieces(type, n) {
        if (type === 'waterfall') return [[n.l ? 2 : 0, 0], [n.r ? 1 : 3, 0], [n.l ? 2 : 0, 1], [n.r ? 1 : 3, 1]];
        if (type === 'wall') return [[n.l ? 2 : 0, n.u ? 2 : 0], [n.r ? 1 : 3, n.u ? 2 : 0], [n.l ? 2 : 0, n.d ? 1 : 3], [n.r ? 1 : 3, n.d ? 1 : 3]];
        const corner = (h, v, diag, cx, cy, inner) => (h && v && !diag ? inner : [h ? cx[0] : cx[1], v ? cy[0] : cy[1]]);
        return [
            corner(n.l, n.u, n.ul, [2, 0], [4, 2], [2, 0]),
            corner(n.r, n.u, n.ur, [1, 3], [4, 2], [3, 0]),
            corner(n.l, n.d, n.dl, [2, 0], [3, 5], [2, 1]),
            corner(n.r, n.d, n.dr, [1, 3], [3, 5], [3, 1])
        ];
    },

    // The shape in a table ([[x, y] x 4] per shape) with these pieces; the closest one if none matches.
    shapeFor(pieces, table) {
        if (!Array.isArray(table) || !table.length) return 0;
        let best = 0, bestScore = -1;
        for (let s = 0; s < table.length; s++) {
            const row = table[s];
            let score = 0;
            for (let i = 0; i < 4; i++) if (row[i] && row[i][0] === pieces[i][0] && row[i][1] === pieces[i][1]) score++;
            if (score === 4) return s;
            if (score > bestScore) { bestScore = score; best = s; }
        }
        return best;
    },

    index(w, h, x, y, z) { return (z * h + y) * w + x; },

    // The autotile at (x, y, z) with its shape worked out again from the tiles around it.
    // map: { width, height, data, loopX, loopY }; tables: { floor, wall, waterfall }.
    reshape(map, x, y, z, tables) {
        const W = map.width, H = map.height;
        const id = Number(map.data[this.index(W, H, x, y, z)]) || 0;
        const type = this.type(id);
        if (!type) return id;
        const k = this.kind(id);
        const same = (dx, dy) => {
            let tx = x + dx, ty = y + dy;
            if (map.loopX) tx = (tx % W + W) % W;
            if (map.loopY) ty = (ty % H + H) % H;
            if (tx < 0 || ty < 0 || tx >= W || ty >= H) return true;
            const other = Number(map.data[this.index(W, H, tx, ty, z)]) || 0;
            return this.isAutotile(other) && this.kind(other) === k;
        };
        const n = { l: same(-1, 0), r: same(1, 0), u: same(0, -1), d: same(0, 1), ul: same(-1, -1), ur: same(1, -1), dl: same(-1, 1), dr: same(1, 1) };
        const table = tables && tables[type];
        return this.make(k, this.shapeFor(this.pieces(type, n), table));
    },

    // Which layer a picked tile goes on when the layer is 'auto': ground autotiles and A5 on 0 (A1's
    // rocks and A2's overlays on 1), B-E on the upper layers (2, or 3 over a tile already on 2).
    autoLayer(id, upperBusy) {
        if (this.isAutotile(id)) {
            const k = this.kind(id);
            if (this.isA1(id) && (k === 2 || k === 3)) return 1;
            return 0;
        }
        if (id >= this.A5) return 0;
        return upperBusy ? 3 : 2;
    },

    // What painting does: [{ index, before, after }] for a brush of tiles (ids: rows of tile ids, a
    // rectangle picked from the palette) with its top-left at (x, y). layer: 0-3 or 'auto'; erase clears.
    paint(map, x, y, brush, tables) {
        const W = map.width, H = map.height;
        const changes = new Map();
        const get = i => (changes.has(i) ? changes.get(i).after : Number(map.data[i]) || 0);
        const set = (i, v) => {
            const before = changes.has(i) ? changes.get(i).before : Number(map.data[i]) || 0;
            changes.set(i, { index: i, before, after: v });
        };
        const view = { width: W, height: H, loopX: map.loopX, loopY: map.loopY, data: { length: W * H * 6 } };
        view.data = new Proxy({}, { get: (t, k) => (k === 'length' ? W * H * 6 : get(Number(k))) });
        const touched = [];
        const rows = brush.erase ? [[0]] : brush.ids;
        for (let r = 0; r < rows.length; r++) {
            for (let c = 0; c < rows[r].length; c++) {
                const tx = x + c, ty = y + r;
                if (tx < 0 || ty < 0 || tx >= W || ty >= H) continue;
                const id = brush.erase ? 0 : Number(rows[r][c]) || 0;
                if (brush.erase) {
                    // The eraser takes the top tile off (the layer picked, or the highest one used).
                    const layers = brush.layer === 'auto' || brush.layer === undefined ? [3, 2, 1, 0] : [Number(brush.layer)];
                    const z = layers.find(l => get(this.index(W, H, tx, ty, l)) !== 0);
                    if (z === undefined) continue;
                    set(this.index(W, H, tx, ty, z), 0);
                    touched.push([tx, ty, z]);
                    continue;
                }
                let z = brush.layer === 'auto' || brush.layer === undefined ? null : Number(brush.layer);
                if (z === null) {
                    const upper2 = get(this.index(W, H, tx, ty, 2));
                    z = this.autoLayer(id, upper2 !== 0 && upper2 !== id);
                    // A third upper tile: the one on 3 moves down to 2 and the new one goes on top.
                    if (z === 3) {
                        const on3 = get(this.index(W, H, tx, ty, 3));
                        if (on3 && on3 !== id) set(this.index(W, H, tx, ty, 2), on3);
                    }
                }
                set(this.index(W, H, tx, ty, z), id);
                touched.push([tx, ty, z]);
            }
        }
        // Autotiles painted and the ones around them take their shapes from their new neighbours.
        const again = new Set();
        for (const [tx, ty, z] of touched) {
            for (let dy = -1; dy <= 1; dy++) {
                for (let dx = -1; dx <= 1; dx++) {
                    let nx = tx + dx, ny = ty + dy;
                    if (map.loopX) nx = (nx % W + W) % W;
                    if (map.loopY) ny = (ny % H + H) % H;
                    if (nx < 0 || ny < 0 || nx >= W || ny >= H) continue;
                    again.add(nx + ',' + ny + ',' + z);
                }
            }
        }
        for (const key of again) {
            const [nx, ny, z] = key.split(',').map(Number);
            const i = this.index(W, H, nx, ny, z);
            const id = get(i);
            if (!this.isAutotile(id)) continue;
            const next = this.reshape(view, nx, ny, z, tables);
            if (next !== id) set(i, next);
        }
        return Array.from(changes.values()).filter(c => c.before !== c.after);
    },

    // The top tile at a spot, for picking it up: { id, layer } (null when the spot is empty).
    topAt(map, x, y) {
        for (const z of [3, 2, 1, 0]) {
            const id = Number(map.data[this.index(map.width, map.height, x, y, z)]) || 0;
            if (id) return { id: this.isAutotile(id) ? this.make(this.kind(id), 0) : id, layer: z };
        }
        return null;
    },

    // ---- The palette: tiles on the tileset pictures ----
    // Where an autotile kind's sample sits on its sheet (tiles), as MZ draws it (first animation frame).
    kindPosition(kind) {
        const tx = kind % 8, ty = Math.floor(kind / 8);
        if (kind < 16) {
            if (kind === 0) return { sheet: 0, x: 0, y: 0 };
            if (kind === 1) return { sheet: 0, x: 0, y: 3 };
            if (kind === 2) return { sheet: 0, x: 6, y: 0 };
            if (kind === 3) return { sheet: 0, x: 6, y: 3 };
            let bx = Math.floor(tx / 4) * 8;
            const by = ty * 6 + (Math.floor(tx / 2) % 2) * 3;
            bx += kind % 2 === 0 ? 0 : 6;
            return { sheet: 0, x: bx, y: by };
        }
        if (kind < 48) return { sheet: 1, x: tx * 2, y: (ty - 2) * 3 };
        if (kind < 80) return { sheet: 2, x: tx * 2, y: (ty - 6) * 2 };
        return { sheet: 3, x: tx * 2, y: Math.floor((ty - 10) * 2.5 + (ty % 2 === 1 ? 0.5 : 0)) };
    },

    // The tile id under a tile position on a sheet (0 A1 ... 8 E), or 0.
    idAt(sheet, x, y) {
        if (x < 0 || y < 0) return 0;
        if (sheet >= 5) return (sheet - 5) * 256 + (x >= 8 ? 128 : 0) + y * 8 + (x % 8);
        if (sheet === 4) return x < 8 && y < 16 ? this.A5 + y * 8 + x : 0;
        // Autotiles: the block the position falls in.
        const kinds = sheet === 0 ? 16 : sheet === 1 ? 32 : 48;
        const first = sheet === 0 ? 0 : sheet === 1 ? 16 : sheet === 2 ? 48 : 80;
        for (let k = first; k < first + kinds; k++) {
            const p = this.kindPosition(k);
            if (p.sheet !== sheet) continue;
            const wide = sheet === 0 && k >= 4 && k % 2 === 1 ? 2 : 2;
            const tall = sheet === 2 || (sheet === 3 && Math.floor(k / 8) % 2 === 1) ? 2 : 3;
            if (x >= p.x && x < p.x + wide && y >= p.y && y < p.y + tall) return this.make(k, 0);
        }
        return 0;
    },

    // The sheet a tile id is on (0 A1 ... 8 E).
    sheetOf(id) {
        if (id >= this.A4) return 3;
        if (id >= this.A3) return 2;
        if (id >= this.A2) return 1;
        if (id >= this.A1) return 0;
        if (id >= this.A5) return 4;
        return 5 + Math.floor(id / 256);
    }
};
//==========================================================
// SECTION 20: DocsDoodads.UNDO (COMMAND-BASED HISTORY STACK)
//==========================================================
DocsDoodads.Undo = {
    undoStack: [],
    redoStack: [],
    maxDepth: 300,
    // Other maps' steps, kept while the editor is on another map: { mapId: { undo, redo, staged, stat } }.
    parked: {},
    parkOrder: [],
    maxParkedMaps: 10,

    labels: {
        edit_doodads: 'Edit doodads', move_doodads: 'Move doodads', adjust_doodads: 'Adjust doodads', trace_collision: 'Trace collision',
        place_doodad: 'Place doodad', paste_doodads: 'Paste doodads', delete_doodads: 'Delete doodads', duplicate_doodads: 'Duplicate doodads',
        scatter_doodads: 'Scatter brush', place_path: 'Draw path', place_prefab: 'Place prefab', sync_prefab: 'Sync prefab copies',
        align_doodads: 'Align', distribute_doodads: 'Distribute', group_doodads: 'Group', ungroup_doodads: 'Ungroup',
        lock_doodads: 'Lock or unlock', hide_doodads: 'Hide or show', z_order_fwd: 'Bring forward', z_order_back: 'Send backward',
        z_order_front: 'Bring to front', z_order_bottom: 'Send to back', create_event: 'Create event', delete_event: 'Delete event',
        duplicate_event: 'Duplicate event', move_event: 'Move event', append_audio_command: 'Add sound to event',
        map_ambient: 'Map setting', map_setting: 'Map setting', world_setting: 'Project setting', map_neighbors: 'Neighbouring maps',
        delete_layer: 'Delete layer', dress_map: 'Dress map', clear_dressing: 'Clear dressing', restore_history: 'Restore from history',
        restore_event: 'Restore event', move_to_map: 'Move to map', copy_to_map: 'Copy to map', mirror_edges: 'Mirror edges',
        terrain_paint: 'Terrain brush stroke', region_paint: 'Region brush stroke', biome_paint: 'Biome brush stroke', nudge_doodads: 'Nudge',
        event_trigger: 'Event trigger', event_priority: 'Event priority', transform_doodad: 'Move / scale',
        set_collision: 'Collision', scatter_erase: 'Scatter eraser', replace_art: 'Replace art'
    },

    markDirty() {
        if (DocsDoodads.Persistence) DocsDoodads.Persistence.dirtyDoodads = true;
    },

    labelFor(command) {
        if (!command) return '';
        if (command.label) return String(command.label);
        const type = String(command.type || '');
        if (this.labels[type]) return this.labels[type];
        if (!type) return 'Edit';
        const words = type.replace(/[_-]+/g, ' ').trim();
        return words.charAt(0).toUpperCase() + words.slice(1);
    },

    // The steps, oldest first: { index, label, done } (done: still applied). The current point is
    // after the last done step.
    history() {
        const done = this.undoStack.map((c, i) => ({ index: i, label: this.labelFor(c), done: true }));
        const undone = this.redoStack.slice().reverse().map((c, i) => ({ index: done.length + i, label: this.labelFor(c), done: false }));
        return done.concat(undone);
    },

    // Undo or redo until `count` steps are applied (0 = before everything that can be undone).
    goTo(count) {
        const target = Math.max(0, Math.min(this.undoStack.length + this.redoStack.length, Math.round(Number(count) || 0)));
        let moved = 0;
        while (this.undoStack.length > target && this.undoStack.length) {
            const cmd = this.undoStack.pop();
            cmd.revert();
            this.redoStack.push(cmd);
            moved++;
        }
        while (this.undoStack.length < target && this.redoStack.length) {
            const cmd = this.redoStack.pop();
            cmd.apply();
            this.undoStack.push(cmd);
            moved++;
        }
        if (moved) {
            this.syncEvents();
            this.markDirty();
            DocsDoodads.Workspace.updateUndoButtons();
            if (DocsDoodads.Workspace.mounted) DocsDoodads.Workspace.refreshInspector();
        }
        return moved;
    },

    // Every map's steps go (after Discard, or a restore from disk).
    clear() {
        this.undoStack = [];
        this.redoStack = [];
        this.parked = {};
        this.parkOrder = [];
        if (DocsDoodads.Workspace.mounted) DocsDoodads.Workspace.updateUndoButtons();
    },

    hasHistory() {
        return this.undoStack.length > 0 || this.redoStack.length > 0;
    },

    // Leaving a map: its steps wait for the editor to come back, with the map data they were made
    // against (staged) and the map file's date, so steps on a map changed in MZ meanwhile are dropped.
    park(mapId, staged, stat) {
        mapId = Number(mapId) || 0;
        if (this.hasHistory()) {
            this.parked[mapId] = { undo: this.undoStack, redo: this.redoStack, staged: staged || null, stat: stat || null };
            this.parkOrder = this.parkOrder.filter(id => id !== mapId).concat([mapId]);
            while (this.parkOrder.length > this.maxParkedMaps) delete this.parked[this.parkOrder.shift()];
        }
        this.undoStack = [];
        this.redoStack = [];
    },

    // Arriving on a map: its steps come back. Returns { steps, staged, dropped } (dropped: the map file
    // changed since, so its steps were let go).
    unpark(mapId, stat) {
        mapId = Number(mapId) || 0;
        const p = this.parked[mapId];
        delete this.parked[mapId];
        this.parkOrder = this.parkOrder.filter(id => id !== mapId);
        this.undoStack = [];
        this.redoStack = [];
        if (!p) return { steps: 0, staged: null, dropped: false };
        const changed = p.stat && stat && (p.stat.mtimeMs !== stat.mtimeMs || p.stat.size !== stat.size);
        if (changed) return { steps: 0, staged: null, dropped: true };
        this.undoStack = p.undo;
        this.redoStack = p.redo;
        return { steps: p.undo.length + p.redo.length, staged: p.staged, dropped: false };
    },

    // Events on the map follow the map data after an undo (they may be new objects since the step).
    syncEvents() {
        const gameMap = typeof window !== 'undefined' ? window.$gameMap : null;
        if (!gameMap || !gameMap._stagedMapData || typeof gameMap.events !== 'function') return;
        const owner = gameMap._stagedMapDataId !== undefined ? gameMap._stagedMapDataId : gameMap.mapId();
        if (owner !== gameMap.mapId()) return;
        const events = gameMap._stagedMapData.events || [];
        for (const ge of gameMap.events()) {
            if (!ge || typeof ge.eventId !== 'function') continue;
            const ev = events[ge.eventId()];
            if (!ev) {
                if (!ge._erased) { ge._erased = true; ge._docsEditorErased = true; }
            } else {
                if (ge._docsEditorErased) { ge._erased = false; delete ge._docsEditorErased; }
                if ((ge.x !== ev.x || ge.y !== ev.y) && typeof ge.locate === 'function') ge.locate(ev.x, ev.y);
            }
        }
    },

    execute(command) {
        if (!command || !command.apply || !command.revert) return;
        DocsDoodads.Usage.lastIndex = null;
        command.apply();
        this.undoStack.push(command);
        if (this.undoStack.length > this.maxDepth) this.undoStack.shift();
        this.redoStack = [];
        this.markDirty();
        DocsDoodads.Workspace.updateUndoButtons();
    },

    undo() {
        if (this.undoStack.length === 0) return false;
        const cmd = this.undoStack.pop();
        cmd.revert();
        this.redoStack.push(cmd);
        this.syncEvents();
        this.markDirty();
        DocsDoodads.Workspace.updateUndoButtons();
        if (DocsDoodads.Workspace.mounted) DocsDoodads.Workspace.refreshInspector();
        if (typeof SoundManager !== 'undefined') SoundManager.playCancel();
        return true;
    },

    redo() {
        if (this.redoStack.length === 0) return false;
        const cmd = this.redoStack.pop();
        cmd.apply();
        this.undoStack.push(cmd);
        this.syncEvents();
        this.markDirty();
        DocsDoodads.Workspace.updateUndoButtons();
        if (DocsDoodads.Workspace.mounted) DocsDoodads.Workspace.refreshInspector();
        if (typeof SoundManager !== 'undefined') SoundManager.playOk();
        return true;
    }
};

//==========================================================
// SECTION 21: DocsDoodads.PERSISTENCE & RECOVERY
//==========================================================
DocsDoodads.Persistence = {
    sessionSnapshots: {},
    // Unsaved event edits (dirtyMap) and doodad or setting edits (dirtyDoodads). Setting either updates
    // the Save button's unsaved dot.
    _dirtyMap: false,
    _dirtyDoodads: false,
    get dirtyMap() { return this._dirtyMap; },
    set dirtyMap(value) { this._dirtyMap = Boolean(value); if (value) this.touch(); this.changed(); },
    get dirtyDoodads() { return this._dirtyDoodads; },
    set dirtyDoodads(value) { this._dirtyDoodads = Boolean(value); if (value) this.touch(); this.changed(); },
    // The maps changed since the last save (for the map tabs' dots).
    touchedMaps: new Set(),

    touch() {
        const gameMap = typeof window !== 'undefined' ? window.$gameMap : null;
        if (gameMap && typeof gameMap.mapId === 'function') this.touchedMaps.add(Number(gameMap.mapId()));
    },

    mapHasUnsaved(mapId) {
        mapId = Number(mapId);
        return this.hasUnsavedWork() && (this.touchedMaps.has(mapId) || Boolean(this.stagedMaps[mapId]));
    },
    // Unsaved event edits for maps other than the current one, keyed by map id.
    stagedMaps: {},

    mapFilePath(mapId) {
        return `data/Map${String(mapId).padStart(3, '0')}.json`;
    },

    // The map file as the workspace opened it, so Save can tell when the MZ editor has changed it since.
    captureSession() {
        const gameMap = window.$gameMap;
        if (!gameMap) return;
        const mapFile = this.mapFilePath(gameMap.mapId());
        // Unsaved event edits keep the snapshot they were made against: Save must still notice MZ's changes.
        if (this.dirtyMap && this.sessionSnapshots[mapFile]) return;
        // A staged copy with no changes is dropped; it is read again, fresh, when it is next needed. While
        // steps can still be undone it is kept (they point into it), unless the file changed on disk:
        // then those steps go with it.
        if (!this.dirtyMap && gameMap._stagedMapData) {
            const snap = this.sessionSnapshots[mapFile], now = DocsDoodads.FS.stat(mapFile);
            const same = Boolean(snap && now && snap.mtimeMs === now.mtimeMs && snap.size === now.size);
            const Undo = DocsDoodads.Undo;
            if (!(same && Undo.hasHistory())) {
                if (Undo.hasHistory()) {
                    Undo.undoStack = [];
                    Undo.redoStack = [];
                }
                gameMap._stagedMapData = null;
                delete gameMap._stagedMapDataId;
            }
        }
        this.sessionSnapshots[mapFile] = DocsDoodads.FS.stat(mapFile);
    },

    // The staged (editable) copy of a map's data, loaded from disk the first time it is needed.
    // It is tagged with its map id so edits can never be written into a different map's file.
    stagedFor(mapId) {
        const gameMap = window.$gameMap;
        if (!gameMap) return null;
        mapId = mapId || gameMap.mapId();
        // Untagged staged data predates map tagging and always belongs to the current map.
        const owner = gameMap._stagedMapDataId !== undefined ? gameMap._stagedMapDataId : gameMap.mapId();
        if (gameMap._stagedMapData && owner === mapId) {
            gameMap._stagedMapDataId = mapId;
            return gameMap._stagedMapData;
        }
        if (gameMap._stagedMapData) this.stagedMaps[owner] = gameMap._stagedMapData;
        let data = this.stagedMaps[mapId];
        delete this.stagedMaps[mapId];
        if (!data) {
            const mapFile = this.mapFilePath(mapId);
            if (!this.sessionSnapshots[mapFile]) this.sessionSnapshots[mapFile] = DocsDoodads.FS.stat(mapFile);
            data = DocsDoodads.FS.readJson(mapFile) || { events: [null] };
        }
        gameMap._stagedMapData = data;
        gameMap._stagedMapDataId = mapId;
        return data;
    },

    // Called before the game loads another map: park this map's staged edits and bring back the next one's.
    onMapChanging(fromId, toId) {
        const gameMap = window.$gameMap;
        if (!gameMap || fromId === toId) return;
        // Steps belong to the map they were made on: they wait while the editor is elsewhere, with the
        // map data they changed, and come back with the map.
        const Undo = DocsDoodads.Undo;
        const owner = gameMap._stagedMapData && gameMap._stagedMapDataId !== undefined ? gameMap._stagedMapDataId : fromId;
        Undo.park(fromId, gameMap._stagedMapData && owner === fromId ? gameMap._stagedMapData : null, DocsDoodads.FS.stat(this.mapFilePath(fromId)));
        if (gameMap._stagedMapData) {
            if (this.dirtyMap) this.stagedMaps[owner] = gameMap._stagedMapData;
        }
        const back = Undo.unpark(toId, DocsDoodads.FS.stat(this.mapFilePath(toId)));
        this._stepsBack = back;
        gameMap._stagedMapData = this.stagedMaps[toId] || back.staged || null;
        if (gameMap._stagedMapData) {
            gameMap._stagedMapDataId = toId;
            delete this.stagedMaps[toId];
        } else {
            delete gameMap._stagedMapDataId;
        }
    },

    // Every map file this save will write: the current map's staged data plus any parked maps.
    pendingMapEntries() {
        const entries = [];
        const gameMap = window.$gameMap;
        if (gameMap && gameMap._stagedMapData) {
            const owner = gameMap._stagedMapDataId !== undefined ? gameMap._stagedMapDataId : gameMap.mapId();
            entries.push({ mapId: owner, data: gameMap._stagedMapData });
        }
        for (const [mapId, data] of Object.entries(this.stagedMaps)) {
            if (!entries.some(e => String(e.mapId) === String(mapId))) entries.push({ mapId: Number(mapId), data });
        }
        return entries;
    },

    checkConflict() {
        if (!window.$gameMap) return false;
        const files = new Set([this.mapFilePath($gameMap.mapId())]);
        for (const entry of this.pendingMapEntries()) files.add(this.mapFilePath(entry.mapId));
        for (const mapFile of files) {
            const snap = this.sessionSnapshots[mapFile];
            if (!snap) continue;
            const current = DocsDoodads.FS.stat(mapFile);
            if (!current) continue;
            if (current.mtimeMs !== snap.mtimeMs || current.size !== snap.size) return true;
        }
        return false;
    },

    saveAll(force = false) {
        if (!window.$gameMap) return false;
        if (!force && this.checkConflict()) {
            DocsDoodads.Workspace.showConflictModal();
            return false;
        }

        const mapEntries = this.pendingMapEntries().map(e => ({ path: this.mapFilePath(e.mapId), data: e.data, indent: 2 }));
        const doodadEntries = DocsDoodads.DataFiles.entriesFor(window.$dataDocsDoodads || {});
        const entries = mapEntries.concat(doodadEntries, [
            { path: DocsDoodads.AssetIndex.libraryPath, data: DocsDoodads.AssetIndex.data, indent: 2 }
        ]);

        try {
            for (const entry of entries) DocsDoodads.FS.createTimestampedBackup(entry.path);
        } catch (error) {
            DocsDoodads.Core.log('Backup creation failed; save cancelled.', error);
            DocsDoodads.Workspace.showToast(`Save cancelled: backup failed (${error.message || error}).`);
            return false;
        }

        const saveResult = DocsDoodads.FS.atomicWriteManyJson(entries);
        if (!saveResult.ok) {
            DocsDoodads.Core.log('Project save transaction failed.', saveResult.error);
            DocsDoodads.Workspace.showToast(`Save failed${saveResult.rolledBack ? '; previous files restored' : ''}: ${saveResult.error}`);
            return false;
        }

        for (const entry of mapEntries) this.sessionSnapshots[entry.path] = DocsDoodads.FS.stat(entry.path);
        this.stagedMaps = {};
        DocsDoodads.DataFiles.removeStale(doodadEntries);

        this.lastSavedAt = Date.now();
        this.dirtyMap = false;
        this.dirtyDoodads = false;
        this.clearRecovery();
        const extra = mapEntries.length > 1 ? ` (${mapEntries.length} maps)` : '';
        DocsDoodads.Workspace.showToast(`Project Saved${extra}! Reload maps in MZ before editing there.`);
        if (DocsDoodads.Workspace.mounted) DocsDoodads.Workspace.updateSaveState(true);
        return true;
    },

    hasUnsavedWork() {
        return this._dirtyMap || this._dirtyDoodads;
    },

    changed() {
        if (!this.hasUnsavedWork()) this.touchedMaps.clear();
        const W = DocsDoodads.Workspace;
        if (W && W.mounted && W.updateSaveState) W.updateSaveState();
        if (W && W.mounted && W.renderMapTabs) W.renderMapTabs();
    },

    // Throws away unsaved work: doodads and settings are read again from disk, event edits are dropped
    // (events moved on this map go back to their saved tiles), and the crash snapshot is removed.
    discardUnsaved() {
        const data = DocsDoodads.DataFiles.readAll();
        window.$dataDocsDoodads = data || {};
        DocsDoodads.migrateData(window.$dataDocsDoodads, 'doodads');
        if (DocsDoodads.World && DocsDoodads.World.invalidate) DocsDoodads.World.invalidate();
        const gameMap = window.$gameMap;
        if (gameMap && this._dirtyMap) {
            const saved = DocsDoodads.FS.readJson(this.mapFilePath(gameMap.mapId()));
            if (saved && saved.events && typeof gameMap.events === 'function') {
                for (const ge of gameMap.events()) {
                    const ev = ge && saved.events[ge.eventId()];
                    if (ev && (ge.x !== ev.x || ge.y !== ev.y)) ge.locate(ev.x, ev.y);
                }
            }
        }
        if (gameMap) {
            gameMap._stagedMapData = null;
            delete gameMap._stagedMapDataId;
        }
        this.stagedMaps = {};
        DocsDoodads.Undo.clear();
        this.dirtyMap = false;
        this.dirtyDoodads = false;
        this.captureSession();
        this.clearRecovery();
    },

    // Snapshots written during this Playtest run are its own autosaves, not crash leftovers.
    bootedAt: Date.now(),

    recoverableSnapshot() {
        const recovery = DocsDoodads.FS.readJson('data/DocsDoodadsRecovery.json');
        if (!recovery || !recovery.timestamp) return null;
        if (recovery.timestamp >= this.bootedAt) return null;
        if (this.bootedAt - recovery.timestamp >= 86400000) return null;
        if (recovery.timestamp === this.answeredRecovery) return null;
        return recovery;
    },

    // Accepted or declined: don't ask again about the same snapshot while this Playtest runs.
    markRecoveryAnswered(recovery) {
        this.answeredRecovery = recovery ? recovery.timestamp : null;
    },

    clearRecovery() {
        const recoveryPath = 'data/DocsDoodadsRecovery.json';
        for (const filePath of [recoveryPath, DocsDoodads.Legacy.pathFor(recoveryPath)]) {
            if (DocsDoodads.FS.fs && DocsDoodads.FS.fs.existsSync(filePath)) {
                try { DocsDoodads.FS.fs.unlinkSync(filePath); } catch(e) {}
            }
        }
    }
};

//==========================================================
// SECTION 22: DocsDoodads.LAYOUT (MULTIPLE SAVED LAYOUTS)
//==========================================================
DocsDoodads.Layout = {
    filePath: 'data/DocsDoodadsLayouts.json',
    presets: {
        Mapping: { drawerWidth: 250, inspectorWidth: 270, thumbSize: 64 },
        Events: { drawerWidth: 230, inspectorWidth: 320, thumbSize: 64 },
        Characters: { drawerWidth: 330, inspectorWidth: 250, thumbSize: 96 },
        Tiles: { drawerWidth: 290, inspectorWidth: 250, thumbSize: 48 },
        Compact: { drawerWidth: 210, inspectorWidth: 230, thumbSize: 56 }
    },
    custom: {},
    current: defaultLayoutName,

    init() {
        try {
            const data = DocsDoodads.FS.readJson(this.filePath);
            if (data && typeof data === 'object') {
                this.custom = data;
            } else {
                this.custom = {};
            }
        } catch(e) {
            this.custom = {};
        }
    },

    get(layoutName) {
        return this.custom[layoutName] || this.presets[layoutName] || this.presets.Mapping;
    },

    getAllNames() {
        this.init();
        const pNames = Object.keys(this.presets);
        const cNames = Object.keys(this.custom);
        return [...pNames, ...cNames.filter(n => !pNames.includes(n))];
    },

    saveCurrentAs(name) {
        if (!name || name.trim() === '') return false;
        name = name.trim();
        const drawer = document.getElementById('dd-drawer-panel');
        const inspector = document.getElementById('dd-inspector-panel');
        const zoom = document.getElementById('dd-thumb-zoom');
        const layoutData = {
            drawerWidth: drawer ? (parseInt(drawer.style.width, 10) || 360) : 360,
            inspectorWidth: inspector ? (parseInt(inspector.style.width, 10) || 280) : 280,
            thumbSize: zoom ? (parseInt(zoom.value, 10) || 96) : 96
        };
        this.custom[name] = layoutData;
        DocsDoodads.FS.atomicWriteJson(this.filePath, this.custom);
        this.current = name;
        return true;
    },

    deleteCustomLayout(name) {
        if (this.custom[name]) {
            delete this.custom[name];
            DocsDoodads.FS.atomicWriteJson(this.filePath, this.custom);
            if (this.current === name) this.apply('Mapping');
            return true;
        }
        return false;
    },

    apply(layoutName) {
        this.init();
        this.current = layoutName;
        const cfg = this.get(layoutName);
        const drawer = document.getElementById('dd-drawer-panel');
        const inspector = document.getElementById('dd-inspector-panel');
        if (drawer) drawer.style.width = cfg.drawerWidth + 'px';
        if (inspector) inspector.style.width = cfg.inspectorWidth + 'px';
        const zoom = document.getElementById('dd-thumb-zoom');
        if (zoom) {
            zoom.value = cfg.thumbSize;
            if (DocsDoodads.Workspace) {
                DocsDoodads.Workspace.thumbSize = cfg.thumbSize;
                DocsDoodads.Workspace.updateVirtualGrid(true);
            }
        }
        if (DocsDoodads.Workspace && typeof DocsDoodads.Workspace.refreshLayoutSelector === 'function') {
            DocsDoodads.Workspace.refreshLayoutSelector();
        }
    }
};

//==========================================================
// SECTION 23: DocsDoodads.AUDIO (PREVIEW & SOUND TRIGGERS)
//==========================================================
DocsDoodads.Audio = {
    currentPlaying: null,
    // The map's BGM/BGS from before the first BGM/BGS preview, restored when previews stop.
    _savedBackground: null,

    // The kind of sound (bgm, bgs, me, se), its MZ name (with the folder inside audio/<kind>/, which
    // MZ plays as a path) and the event command that plays it.
    soundFor(asset) {
        const path = String(asset.path || '').replace(/\\/g, '/');
        const m = /(?:^|\/)audio\/(bgm|bgs|me|se)\/(.+)\.[^/.]+$/i.exec(path);
        const type = m ? m[1].toLowerCase() : 'se';
        const name = m ? m[2] : String(asset.fileName || '').replace(/\.[^/.]+$/, '');
        return { type, name, code: { bgm: 241, bgs: 245, me: 249, se: 250 }[type] };
    },

    playPreview(asset) {
        if (!asset || asset.category !== 'Audio') return;
        this.stopPreview();
        if (typeof AudioManager === 'undefined') return;

        const { type, name: baseName } = this.soundFor(asset);
        const sound = { name: baseName, volume: 90, pitch: 100, pan: 0 };

        if ((type === 'bgm' || type === 'bgs') && !this._savedBackground) {
            this._savedBackground = { bgm: AudioManager.saveBgm(), bgs: AudioManager.saveBgs() };
        }
        if (type === 'bgm') AudioManager.playBgm(sound);
        else if (type === 'bgs') AudioManager.playBgs(sound);
        else if (type === 'me') AudioManager.playMe(sound); // MZ resumes the BGM after an ME
        else AudioManager.playSe(sound);
        this.currentPlaying = { type, name: baseName };
    },

    stopPreview() {
        const playing = this.currentPlaying;
        this.currentPlaying = null;
        if (!playing || typeof AudioManager === 'undefined') return;
        if (playing.type === 'se') AudioManager.stopSe();
        else if (playing.type === 'me') AudioManager.stopMe();
        else if (this._savedBackground) {
            const saved = this._savedBackground;
            this._savedBackground = null;
            AudioManager.replayBgm(saved.bgm);
            AudioManager.replayBgs(saved.bgs);
        }
    }
};

//==========================================================
// SECTION 24: DocsDoodads.IMPORT (TRANSACTIONAL EXPLORER INGESTION)
//==========================================================
DocsDoodads.Import = {
    imageExtensions: new Set(['.png', '.jpg', '.jpeg', '.webp']),
    audioExtensions: new Set(['.ogg', '.m4a', '.wav']),
    destinations: [
        'img/doodads', 'img/characters', 'img/faces', 'img/parallaxes',
        'img/pictures', 'img/tilesets', 'audio/bgm', 'audio/bgs',
        'audio/me', 'audio/se'
    ],

    isSupported(filePath) {
        if (!DocsDoodads.FS.path) return false;
        const ext = DocsDoodads.FS.path.extname(filePath).toLowerCase();
        return this.imageExtensions.has(ext) || this.audioExtensions.has(ext);
    },

    detectDestination(filePath) {
        const path = DocsDoodads.FS.path;
        if (!path) return null;
        const fileName = path.basename(filePath);
        const ext = path.extname(fileName).toLowerCase();
        const lower = fileName.toLowerCase();
        const normalizedSource = String(filePath).replace(/\\/g, '/').toLowerCase();

        if (this.audioExtensions.has(ext)) {
            if (normalizedSource.includes('/bgm/') || /(^|[_\-.])bgm([_\-.]|$)/.test(lower)) return 'audio/bgm';
            if (normalizedSource.includes('/bgs/') || /(^|[_\-.])bgs([_\-.]|$)/.test(lower)) return 'audio/bgs';
            if (normalizedSource.includes('/me/') || /(^|[_\-.])me([_\-.]|$)/.test(lower)) return 'audio/me';
            return 'audio/se';
        }
        if (!this.imageExtensions.has(ext)) return null;

        if (normalizedSource.includes('/characters/') || lower.startsWith('$') || lower.includes('character') || lower.includes('actor')) return 'img/characters';
        if (normalizedSource.includes('/faces/') || lower.includes('face')) return 'img/faces';
        if (normalizedSource.includes('/parallaxes/') || lower.includes('parall')) return 'img/parallaxes';
        if (normalizedSource.includes('/pictures/') || /(^|[_\-.])pic(ture)?([_\-.]|$)/.test(lower)) return 'img/pictures';
        if (normalizedSource.includes('/tilesets/') || lower.includes('tile')) return 'img/tilesets';
        return 'img/doodads';
    },

    normalizeDestination(destination) {
        const normalized = String(destination || '').replace(/\\/g, '/').replace(/^\.\//, '').replace(/\/$/, '');
        return this.destinations.includes(normalized) ? normalized : null;
    },

    validateExecutionPlan(plan) {
        const path = DocsDoodads.FS.path;
        if (!path || !plan || !Array.isArray(plan.operations)) return 'Import plan is invalid.';
        const projectRoot = path.resolve(plan.projectRoot || '.');
        for (const operation of plan.operations) {
            if (!operation || !operation.source || !operation.destination || !this.isSupported(operation.source)) {
                return 'Import plan contains an invalid or unsupported operation.';
            }
            const destination = path.resolve(operation.destination);
            const relative = path.relative(projectRoot, destination).replace(/\\/g, '/');
            const insideProject = relative && !relative.startsWith('../') && relative !== '..' && !path.isAbsolute(relative);
            const insideAllowedFolder = this.destinations.some(folder => relative.startsWith(folder + '/'));
            if (!insideProject || !insideAllowedFolder) {
                return `Import destination is outside an allowed project asset folder: ${operation.destination}`;
            }
        }
        return null;
    },

    collectFiles(sourcePaths) {
        const fs = DocsDoodads.FS.fs;
        const path = DocsDoodads.FS.path;
        const files = [];
        const errors = [];
        // For files inside a dropped folder: their sub-folder path below that dropped folder ('' at its top level).
        const relativeDirs = new Map();
        if (!fs || !path) return { files, errors: [{ path: '', message: 'Filesystem access is unavailable.' }], relativeDirs };

        const pending = Array.from(sourcePaths || []).filter(Boolean).map(p => ({ current: path.resolve(String(p)), root: null }));
        while (pending.length > 0) {
            const { current, root } = pending.pop();
            try {
                const stat = fs.statSync(current);
                if (stat.isDirectory()) {
                    const children = fs.readdirSync(current).sort().reverse();
                    for (const child of children) pending.push({ current: path.join(current, child), root: root || current });
                } else if (stat.isFile()) {
                    files.push(current);
                    if (root) relativeDirs.set(current, path.relative(root, path.dirname(current)));
                }
            } catch (error) {
                errors.push({ path: current, message: error && error.message ? error.message : String(error) });
            }
        }
        files.sort((a, b) => a.localeCompare(b));
        return { files, errors, relativeDirs };
    },

    // Plain-language summary of a runAssetImport result for the toast.
    describeResult(result) {
        const path = DocsDoodads.FS.path;
        const baseName = (p) => path ? path.basename(String(p)) : String(p).split(/[\\/]/).pop();
        if (result.ok) {
            const parts = [`Imported ${result.imported.length} file(s)`];
            if (result.duplicates && result.duplicates.length) parts.push(`${result.duplicates.length} identical file(s) skipped`);
            if (result.skipped && result.skipped.length) parts.push(`${result.skipped.length} skipped because the name already exists`);
            return parts.join(', ') + '.';
        }
        if (result.cancelled) return `Import cancelled${result.rolledBack ? '; copied files were rolled back' : ''}.`;
        const collision = (result.errors || []).find(error => error.message === 'Destination already exists.');
        if (collision) return `Import cancelled: ${baseName(collision.destination || collision.path)} already exists. Nothing was imported.`;
        const reason = result.errors && result.errors[0] ? result.errors[0].message : 'Unknown import error';
        return `Import failed${result.rolledBack ? ' and was rolled back' : ''}: ${reason}`;
    },

    filesEqual(firstPath, secondPath) {
        const fs = DocsDoodads.FS.fs;
        if (!fs) return false;
        try {
            const firstStat = fs.statSync(firstPath);
            const secondStat = fs.statSync(secondPath);
            if (firstStat.size !== secondStat.size) return false;
            return fs.readFileSync(firstPath).equals(fs.readFileSync(secondPath));
        } catch (error) {
            return false;
        }
    },

    planBatch(sourcePaths, options = {}) {
        const fs = DocsDoodads.FS.fs;
        const path = DocsDoodads.FS.path;
        const plan = {
            projectRoot: path ? path.resolve(options.projectRoot || '.') : '.',
            collisionPolicy: options.collisionPolicy || 'rename',
            operations: [], unsupported: [], duplicates: [], skipped: [], errors: []
        };
        if (!fs || !path) {
            plan.errors.push({ path: '', message: 'Filesystem access is unavailable.' });
            return plan;
        }

        const collected = this.collectFiles(sourcePaths);
        plan.errors.push(...collected.errors);
        const reserved = new Map();
        const reservedKey = destination => process.platform === 'win32' ? destination.toLowerCase() : destination;

        for (const source of collected.files) {
            if (!this.isSupported(source)) {
                plan.unsupported.push(source);
                continue;
            }

            const requestedDestination = options.destination && options.destination !== 'auto'
                ? options.destination
                : this.detectDestination(source);
            const relativeFolder = this.normalizeDestination(requestedDestination);
            if (!relativeFolder) {
                plan.errors.push({ path: source, message: `Unsupported destination: ${requestedDestination}` });
                continue;
            }

            let targetFolder = path.resolve(plan.projectRoot, relativeFolder);
            // img/doodads belongs to this plugin and is scanned recursively, so folders inside a dropped
            // folder are kept there; RPG Maker's own folders (characters, faces, audio...) stay flat.
            const droppedDir = collected.relativeDirs && collected.relativeDirs.get(source);
            if (droppedDir && relativeFolder === 'img/doodads') {
                const segments = droppedDir.split(/[\\/]+/)
                    .filter(segment => segment && segment !== '.' && segment !== '..')
                    .map(segment => segment.replace(/[<>:"|?*\x00-\x1f]/g, '_'));
                if (segments.length) targetFolder = path.join(targetFolder, ...segments);
            }
            const rootPrefix = plan.projectRoot.endsWith(path.sep) ? plan.projectRoot : plan.projectRoot + path.sep;
            if (targetFolder !== plan.projectRoot && !targetFolder.startsWith(rootPrefix)) {
                plan.errors.push({ path: source, message: 'Import destination escapes the project root.' });
                continue;
            }

            const fileName = path.basename(source);
            const ext = path.extname(fileName);
            const base = path.basename(fileName, ext);
            let destination = path.join(targetFolder, fileName);
            let overwrite = false;
            let suffix = 0;

            while (fs.existsSync(destination) || reserved.has(reservedKey(destination))) {
                const comparisonSource = reserved.has(reservedKey(destination)) ? reserved.get(reservedKey(destination)) : destination;
                if (this.filesEqual(source, comparisonSource)) {
                    plan.duplicates.push({ source, destination });
                    destination = null;
                    break;
                }

                const policy = typeof options.collisionPolicy === 'function'
                    ? options.collisionPolicy({ source, destination })
                    : plan.collisionPolicy;
                if (policy === 'skip') {
                    plan.skipped.push({ source, destination, reason: 'collision' });
                    destination = null;
                    break;
                }
                if (policy === 'overwrite') {
                    overwrite = true;
                    break;
                }
                if (policy === 'error') {
                    plan.errors.push({ path: source, destination, message: 'Destination already exists.' });
                    destination = null;
                    break;
                }
                suffix++;
                destination = path.join(targetFolder, `${base}_${suffix}${ext}`);
            }
            if (!destination) continue;

            reserved.set(reservedKey(destination), source);
            plan.operations.push({
                source,
                destination,
                relativeDestination: path.relative(plan.projectRoot, destination).replace(/\\/g, '/'),
                overwrite,
                kind: this.audioExtensions.has(path.extname(source).toLowerCase()) ? 'audio' : 'image'
            });
        }
        return plan;
    },

    async executeBatchAsync(plan, options = {}) {
        const fs = DocsDoodads.FS.fs;
        const path = DocsDoodads.FS.path;
        const fsp = fs && fs.promises;
        const result = {
            ok: false,
            imported: [],
            overwritten: [],
            duplicates: (plan && plan.duplicates) ? plan.duplicates.slice() : [],
            skipped: (plan && plan.skipped) ? plan.skipped.slice() : [],
            unsupported: (plan && plan.unsupported) ? plan.unsupported.slice() : [],
            errors: (plan && plan.errors) ? plan.errors.slice() : [],
            rolledBack: false,
            cancelled: false
        };
        if (!fs || !path || !fsp || !plan || result.errors.length > 0) return result;
        const validationError = this.validateExecutionPlan(plan);
        if (validationError) {
            result.errors.push({ message: validationError });
            return result;
        }

        const completed = [];
        const tempFiles = [];
        const cancellationToken = options.cancellationToken || null;
        const transactionId = `${Date.now()}-${Math.random().toString(36).slice(2)}`;
        const exists = async filePath => {
            try { await fsp.stat(filePath); return true; } catch (error) { return false; }
        };
        const removeIfPresent = async filePath => {
            try { await fsp.unlink(filePath); } catch (error) {
                if (!error || error.code !== 'ENOENT') throw error;
            }
        };

        try {
            for (let index = 0; index < plan.operations.length; index++) {
                if (cancellationToken && cancellationToken.cancelled) {
                    const cancellation = new Error('Import cancelled.');
                    cancellation.code = 'DD_IMPORT_CANCELLED';
                    throw cancellation;
                }

                const operation = plan.operations[index];
                await fsp.mkdir(path.dirname(operation.destination), { recursive: true });
                const existed = await exists(operation.destination);
                if (existed && !operation.overwrite) {
                    throw new Error(`Destination changed after import preview: ${operation.destination}`);
                }

                let backup = null;
                if (existed) {
                    backup = `${operation.destination}.ddimport-${transactionId}.bak`;
                    await fsp.copyFile(operation.destination, backup);
                    tempFiles.push(backup);
                }

                const temporary = `${operation.destination}.ddimport-${transactionId}-${index}.tmp`;
                tempFiles.push(temporary);
                await fsp.copyFile(operation.source, temporary);
                if (existed) {
                    completed.push({ operation, existed, backup });
                    await fsp.copyFile(temporary, operation.destination);
                    await removeIfPresent(temporary);
                } else {
                    await fsp.rename(temporary, operation.destination);
                    completed.push({ operation, existed, backup });
                }

                result.imported.push(operation.destination);
                if (existed) result.overwritten.push(operation.destination);
                if (typeof options.onProgress === 'function') {
                    options.onProgress({
                        completed: index + 1,
                        total: plan.operations.length,
                        source: operation.source,
                        destination: operation.destination
                    });
                }

                if (cancellationToken && cancellationToken.cancelled) {
                    const cancellation = new Error('Import cancelled.');
                    cancellation.code = 'DD_IMPORT_CANCELLED';
                    throw cancellation;
                }
            }

            for (const record of completed) {
                if (record.backup) await removeIfPresent(record.backup);
            }
            result.ok = true;
            return result;
        } catch (error) {
            result.cancelled = Boolean(error && error.code === 'DD_IMPORT_CANCELLED');
            result.errors.push({ message: error && error.message ? error.message : String(error) });
            for (let index = completed.length - 1; index >= 0; index--) {
                const record = completed[index];
                try {
                    if (record.existed && record.backup && await exists(record.backup)) {
                        await fsp.copyFile(record.backup, record.operation.destination);
                    } else if (!record.existed) {
                        await removeIfPresent(record.operation.destination);
                    }
                } catch (rollbackError) {
                    result.errors.push({ path: record.operation.destination, message: `Rollback failed: ${rollbackError.message || rollbackError}` });
                }
            }
            for (const temporary of tempFiles) {
                try { await removeIfPresent(temporary); } catch (cleanupError) {}
            }
            result.imported = [];
            result.overwritten = [];
            result.rolledBack = completed.length > 0;
            return result;
        }
    }
};


